import{_ as u,a0 as a,w as d,s as n,ao as s,I as e,a1 as o,A as l,x as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Git 入門：術語基礎 | LCTT x X-CMD","titleTemplate":false,"description":"Git 入門：術語基礎 | LCTT (202101) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Git 入門：術語基礎 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Git 入門：術語基礎 | LCTT (202101) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202101/20190204 Getting started with Git- Terminology 101","title":"Git 入門：術語基礎","tag":"202101","desc":""},"relativePath":"202101/20190204 Getting started with Git- Terminology 101.md","filePath":"[post].md"}'),b={name:"202101/20190204 Getting started with Git- Terminology 101.md"};function m(p,t,y,g,f,G){const i=a("Link");return d(),n("div",null,[t[34]||(t[34]=s('<h1 id="git-入門-術語基礎" tabindex="-1">Git 入門：術語基礎 <a class="header-anchor" href="#git-入門-術語基礎" aria-label="Permalink to “Git 入門：術語基礎”">​</a></h1><blockquote><p>想學習 Git？看看這個最重要的術語和命令的快速總結。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202101/08/171156gu9l8dvulxmxom6d.jpg" alt=""></p><p>如今，對於任何希望跟蹤他們的變化的人來説，版本控制是一個重要的工具。它對程序員、系統管理員和<ruby>網站可靠性工程師<rt>site reliability engineers</rt></ruby>（SRE）都特別有用。確保可以從錯誤中恢復到已知的良好狀態是一個巨大的勝利，比以前給複製的文件添加 <code>.old</code> 後綴的策略更友好。</p><p>但學習 Git 這件事往往被告訴大家“投身開源”的好心同行們過度簡化了。在你還不明白之前，就有人要你給一個從<ruby>上游<rt>upstream</rt></ruby> <ruby>變基<rt>rebase</rt></ruby>的<ruby>拉取請求<rt>pull request</rt></ruby>（PR）或<ruby>合併請求<rt>merge request</rt></ruby>（MR），然後他們才能從你的<ruby>遠程版本庫<rt>remote</rt></ruby>合併 —— 而且一定會刪除<ruby>合併提交<rt>merge commits</rt></ruby>。無論你想給開源項目做出什麼好的貢獻，當你看到這些你不認識的單詞時，都會覺得難以融入。</p><p><img src="https://opensource.com/sites/default/files/uploads/git_cheat_sheet_cover.jpg" alt="Git 速查表封面圖" title="Git Cheat Sheet cover image"></p>',6)),e("ul",null,[e("li",null,[o(i,{href:"https://opensource.com/downloads/cheat-sheet-git"},{default:l(()=>[...t[0]||(t[0]=[r("下載",-1)])]),_:1}),t[1]||(t[1]=r(" 我們的 Git 速查表。",-1))])]),e("p",null,[t[3]||(t[3]=r("如果你有一兩個月的時間和足夠的好奇心，",-1)),o(i,{href:"https://git-scm.com/about"},{default:l(()=>[...t[2]||(t[2]=[r("Git SCM",-1)])]),_:1}),t[4]||(t[4]=r(" 是你需要學習所有術語的權威來源。但如果你正在尋找來自實踐的總結，請繼續閲讀。",-1))]),t[35]||(t[35]=s('<h3 id="提交就是提醒" tabindex="-1">提交就是提醒 <a class="header-anchor" href="#提交就是提醒" aria-label="Permalink to “提交就是提醒”">​</a></h3><p>對我來説，Git 最難理解的部分是 Git 最簡單的概念：一個<ruby>提交<rt>commit</rt></ruby>就是一個內容的集合，包括一個關於描述的信息，以及之前的提交。沒有固有的代碼發佈策略，甚至沒有內置的明確建議。這個內容甚至不一定是代碼 —— 可以是<em>任何</em>你想添加到版本庫的東西。<ruby>提交消息<rt>commit message</rt></ruby>會對這些內容進行註釋。</p><p>我喜歡把提交信息看作是給未來的自己的禮物：它可能會提到你編輯的文件，但更重要的是它提醒你修改這些文件的意圖。添加更多關於你為什麼編輯這些內容的信息，可以幫助任何使用你的版本庫的人，即使那個人是你。</p><h3 id="origin-master-在哪裏" tabindex="-1">origin/master 在哪裏？ <a class="header-anchor" href="#origin-master-在哪裏" aria-label="Permalink to “origin/master 在哪裏？”">​</a></h3><p>要知道自己在 Git 項目中的位置，首先把它想成一棵樹。所有 Git 項目都有一個根目錄，類似於文件系統的根目錄。所有的提交都是這個根目錄下的分支。這樣一來，分支只是一個提交的指針。按照慣例，<code>master</code> 是根目錄下默認的分支名稱。（LCTT 譯註：世界變得快，原文發表於 2019 年，而現在有些地方開始用 <code>main</code> 替代這個名字。）</p><p>由於 Git 是一個分佈式的版本控制系統，同一個代碼庫分佈在多個地方，所以人們經常用<ruby>版本庫<rt>repository</rt></ruby>這個詞來表示同一個項目的所有副本。（LCTT 譯註：“repository” 英文原意是倉庫、存儲庫，在計算機環境中，常用於版本控制、軟件分發等方面，有時候會統一譯作“倉庫”、“存儲庫”。但我們認為，應該根據不同語境採用更有指向性的譯法。在 Git 等版本控制語境中，採用“版本庫”；在軟件分發方面，採用“軟件庫”；其它泛指或不確定的語境中，可採用“倉庫”、“存儲庫”譯法。）有<ruby>本地版本庫<rt>local repository</rt></ruby>，這是你編輯代碼的地方（稍後會有更多的介紹），還有<ruby>遠程版本庫<rt>remote repository</rt></ruby>，這是你完成後想把代碼發送到的地方。遠程版本庫可以在任何地方，甚至在你的本地版本庫所在的同一台計算機上，但它們通常託管在 GitLab 或 GitHub 等版本庫服務上。</p><h3 id="我在哪裏" tabindex="-1">我在哪裏？ <a class="header-anchor" href="#我在哪裏" aria-label="Permalink to “我在哪裏？”">​</a></h3><p>雖然不是官方的賣點，但迷路也是 Git 倉庫的“樂趣”之一。你可以通過這套可靠的命令來找到自己的方向：</p><ul><li><code>git branch</code> —— 找到你所在的分支。</li><li><code>git log</code> —— 查看你正在進行的提交。</li><li><code>git status</code> —— 查看自上次提交以來你所做的編輯。</li><li><code>git remote</code> —— 查看你正在跟蹤的遠程倉庫。</li></ul><p>用這些命令來定位自己的方向，當你被卡住的時候，會讓你有一種方向感。</p><h3 id="我是否已將我的提交暫存或緩存起來" tabindex="-1">我是否已將我的提交暫存或緩存起來？ <a class="header-anchor" href="#我是否已將我的提交暫存或緩存起來" aria-label="Permalink to “我是否已將我的提交暫存或緩存起來？”">​</a></h3><p>你電腦上的代碼俗稱為你的<ruby>工作空間<rt>workspace</rt></ruby>。但不是很明顯的是，當你在 Git 倉庫中時，你還有兩個（是的，兩個！）其他位置：<ruby>索引<rt>index</rt></ruby>和<ruby>暫存<rt>stash</rt></ruby>。當你寫了一些內容，然後<strong>添加</strong>時，你是把它添加到索引中，也就是準備提交的緩存內容。有的時候，你的索引中的文件還沒有準備好提交，但你想查看另一個分支。這時，暫存就派上用場了。你可以使用 <code>git stash</code> 將索引了但尚未提交的文件存儲到暫存區中。當你準備好取回文件時，運行 <code>git stash pop</code> 將更改帶回索引中。</p><p>下面是一些你需要使用暫存區和緩存區的命令：</p><ul><li><code>git diff ...origin/master</code> —— 顯示最近的本地提交和遠程的 <code>origin</code> 版本庫的 <code>master</code> 分支之間的差異。</li><li><code>git diff --cached</code> —— 顯示最近的本地提交與添加到本地索引的內容之間的任何差異。</li><li><code>git stash</code> —— 將索引的（已添加但未提交的）文件放在暫存區堆棧中。</li><li><code>git stash list</code> —— 顯示暫存區堆棧中的變化。</li><li><code>git stash pop</code> —— 將最近的變化從暫存庫中刪除。</li></ul><h3 id="無頭騎士" tabindex="-1">無頭騎士 <a class="header-anchor" href="#無頭騎士" aria-label="Permalink to “無頭騎士”">​</a></h3><p>Git 裏面有各種比喻。當我想到 <code>HEAD</code> 是哪裏的時候，我就會想到火車線路。如果你最終處於<ruby>脱離的 HEAD<rt>detached HEAD</rt></ruby>模式，就意味着你已經脱離了這個隱喻的軌道。</p><p><code>HEAD</code> 是指向當前簽出分支中最近一次提交的指針。默認的“<ruby>簽出<rt>checkout</rt></ruby>”是指當你創建一個 Git 倉庫並進入到 <code>master</code> 分支的時候。每次創建或修改到另一個分支時，你都會切換到該分支行。如果你在當前分支的某處進行 <code>git checkout &lt;commit&gt;</code>，<code>HEAD</code> 就會移動到該提交。如果沒有提交歷史記錄將你的當前提交連接到已簽出的提交，那麼你將處於脱離的 <code>HEAD</code> 狀態。如果你找不到 <code>HEAD</code> 的位置，你可以隨時用 <code>git reset --hard origin/master</code> 來刪除修改，回到已知狀態。<em>警告：這將刪除你上次推送到 <code>master</code> 後的任何改動。</em></p><h3 id="你是上游還是下游" tabindex="-1">你是上游還是下游？ <a class="header-anchor" href="#你是上游還是下游" aria-label="Permalink to “你是上游還是下游？”">​</a></h3><p>你的項目的本地副本被認為是你的本地版本庫，它可能有也可能沒有遠程版本庫 —— 遠程版本庫的副本是用於協作或保存的。也可能還有一個<ruby>上游<rt>upstream</rt></ruby>版本庫，在那裏，項目的第三個副本由不同的貢獻者託管和維護。</p><p>例如，假設我想為 Kubernetes 做貢獻。我會首先將 <code>kubernetes/kubernetes</code> 項目<ruby>復刻<rt>fork</rt></ruby>到我的賬户下 <code>mbbroberg/kubernetes</code>。然後我會將我的項目克隆到我的本地工作區。在這種情況下，我的本地克隆是我的本地倉庫，<code>mbbroberg/kubernetes</code> 是我的遠程倉庫，<code>kubernetes/kubernetes</code> 是上游。</p><h3 id="合併的隱喻" tabindex="-1">合併的隱喻 <a class="header-anchor" href="#合併的隱喻" aria-label="Permalink to “合併的隱喻”">​</a></h3>',21)),e("p",null,[t[7]||(t[7]=r("當你深入 Git 分支時，根系統的視覺效果就會和火車軌道的形象合二為一。分支通常被用作開發一個新功能的方式，最終你想把它",-1)),t[8]||(t[8]=e("ruby",null,[r("合併"),e("rt",null,"merge")],-1)),t[9]||(t[9]=r("到主分支中。當這樣做時，Git 會按順序保留共同的提交歷史，然後將你的分支的新提交追加到歷史中。這個過程有一大堆的細節：是否",-1)),t[10]||(t[10]=e("ruby",null,[r("變基"),e("rt",null,"rebase")],-1)),t[11]||(t[11]=r("，是否添加一個",-1)),t[12]||(t[12]=e("ruby",null,[r("合併提交"),e("rt",null,"merge commit")],-1)),t[13]||(t[13]=r("，",-1)),o(i,{href:"https://opensource.com/users/bclaster"},{default:l(()=>[...t[5]||(t[5]=[r("Brent Laster",-1)])]),_:1}),t[14]||(t[14]=r(" 在《",-1)),o(i,{href:"https://opensource.com/article/18/6/git-reset-revert-rebase-commands"},{default:l(()=>[...t[6]||(t[6]=[r("如何在 Git 中重置、恢復和返回之前的狀態",-1)])]),_:1}),t[15]||(t[15]=r("》中會有更詳細的探討。",-1))]),t[36]||(t[36]=e("h3",{id:"我想現在就去-git",tabindex:"-1"},[r("我想現在就去 Git "),e("a",{class:"header-anchor",href:"#我想現在就去-git","aria-label":"Permalink to “我想現在就去 Git”"},"​")],-1)),e("p",null,[t[17]||(t[17]=r("要掌握 Git 命令的世界，有大量的術語和需要探索的地方。我希望這篇關於日常使用術語的第一人稱探索能幫助你適應這一切。如果你覺得自己被卡住了或者遇到了挫折，歡迎在 Twitter ",-1)),o(i,{href:"https://twitter.com/mbbroberg"},{default:l(()=>[...t[16]||(t[16]=[r("@mbbroberg",-1)])]),_:1}),t[18]||(t[18]=r(" 上聯繫我。",-1))]),t[37]||(t[37]=s('<h4 id="回顧" tabindex="-1">回顧 <a class="header-anchor" href="#回顧" aria-label="Permalink to “回顧”">​</a></h4><ul><li><ruby>提交<rt>Commit</rt></ruby> —— 將當前索引的內容保存在一個新的提交中，並附上用户描述更改的日誌信息。</li><li><ruby>分支<rt>Branch</rt></ruby> —— 指向一個提交的指針。</li><li><code>master</code> —— 第一個分支的默認名稱。</li><li><code>HEAD</code> —— 指向當前分支上最近一次提交的指針。</li><li><ruby>合併<rt>Merge</rt></ruby> —— 合併兩個或多個提交的歷史。</li><li><ruby>工作空間<rt>Workspace</rt></ruby> —— Git 倉庫本地副本的通俗名稱。</li><li><ruby>工作樹<rt>Working tree</rt></ruby> —— 工作區中的當前分支；任何時候你都可以在 <code>git status</code> 的輸出中看到這個。</li><li><ruby>緩存<rt>Cache</rt></ruby> —— 用於臨時存儲未提交的變更的空間。</li><li><ruby>索引<rt>Index</rt></ruby> —— 變更提交前存儲其變化的緩存。</li><li>跟蹤和未跟蹤的文件 —— 沒有被索引緩存的文件或尚未加入其中的文件。</li><li><ruby>暫存<rt>Stash</rt></ruby> —— 另一個緩存，作為一個堆棧，在這裏可以存儲更改而不需要提交它們。</li><li><code>origin</code> —— 遠程版本庫的默認名稱。</li><li><ruby>本地倉庫<rt>Local repository</rt></ruby> —— 也就是你在工作站上保存 Git 倉庫副本的地方。</li><li><ruby>遠程存儲庫<rt>Remote repository</rt></ruby> —— Git 存儲庫的第二副本，你可以在這裏推送變更以便協作或備份。</li><li><ruby>上游存儲庫<rt>Upstream repository</rt></ruby> —— 你跟蹤的遠程存儲庫的通俗説法。</li><li><ruby>拉取請求<rt>Pull request</rt></ruby> —— 這是 GitHub 的專用術語，用於讓其他人知道你推送到倉庫分支的變化。</li><li><ruby>合併請求<rt>Merge request</rt></ruby> —— 這是 GitLab 的專用術語，用於讓其他人知道你推送到倉庫分支的變化。</li><li><code>origin/master</code> —— 遠程版本庫及其主要分支的默認名稱。</li></ul><p>後記：雙關語是 Git 最好的部分之一，願你喜歡。</p><hr>',4)),e("p",null,[t[20]||(t[20]=r("via: ",-1)),o(i,{href:"https://opensource.com/article/19/2/git-terminology"},{default:l(()=>[...t[19]||(t[19]=[r("https://opensource.com/article/19/2/git-terminology",-1)])]),_:1})]),e("p",null,[t[25]||(t[25]=r("作者：",-1)),o(i,{href:"https://opensource.com/users/mbbroberg"},{default:l(()=>[...t[21]||(t[21]=[r("Matthew Broberg",-1)])]),_:1}),t[26]||(t[26]=r(" 選題：",-1)),o(i,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[22]||(t[22]=[r("lujun9972",-1)])]),_:1}),t[27]||(t[27]=r(" 譯者：",-1)),o(i,{href:"https://github.com/wxy"},{default:l(()=>[...t[23]||(t[23]=[r("wxy",-1)])]),_:1}),t[28]||(t[28]=r(" 校對：",-1)),o(i,{href:"https://github.com/wxy"},{default:l(()=>[...t[24]||(t[24]=[r("wxy",-1)])]),_:1})]),e("p",null,[t[31]||(t[31]=r("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[29]||(t[29]=[r("LCTT",-1)])]),_:1}),t[32]||(t[32]=r(" 原創編譯，",-1)),o(i,{href:"https://linux.cn/"},{default:l(()=>[...t[30]||(t[30]=[r("Linux中國",-1)])]),_:1}),t[33]||(t[33]=r(" 榮譽推出",-1))])])}const k=u(b,[["render",m]]);export{x as __pageData,k as default};
